const imports=`global using System;\nglobal using System.IO;\nglobal using System.Linq;\nglobal using System.Text;\nglobal using System.Text.Json;\nglobal using System.Globalization;\nglobal using System.Collections.Generic;\nglobal using System.Threading;\nglobal using System.Threading.Tasks;\nglobal using System.Security.Claims;\nglobal using System.Runtime.CompilerServices;\nglobal using Microsoft.AspNetCore.Http;\nglobal using Microsoft.AspNetCore.Http.Features;\nglobal using Microsoft.AspNetCore.Routing;\nglobal using Microsoft.AspNetCore.Routing.Patterns;\nglobal using Microsoft.AspNetCore.Authorization;\nglobal using Microsoft.Extensions.DependencyInjection;\nglobal using Microsoft.Extensions.Options;\nglobal using Microsoft.Extensions.Primitives;\n`;
const helper=imports+`
namespace DotnetWeb;
public static class Check {
 public static int Assertions;
 public static void True(bool value){Assertions++;if(!value)throw new Exception("Expected true");}
 public static void Equal<T>(T expected,T actual){Assertions++;if(expected is CancellationToken left&&actual is CancellationToken right){if(!left.Equals(right))throw new Exception("Expected identical CancellationToken");return;}var a=JsonSerializer.Serialize(expected);var b=JsonSerializer.Serialize(actual);if(a!=b)throw new Exception($"Expected {a}, got {b}");}
 public static void Status(int expected,IResult result){Assertions++;int? declared=(result as IStatusCodeHttpResult)?.StatusCode;int effective=declared??200;if(effective!=expected)throw new Exception($"Expected HTTP {expected}, got {(declared.HasValue?declared.Value.ToString():"execution default")} for "+result.GetType().Name);}
 public static void Throws<T>(Action action) where T:Exception {Assertions++;try{action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
 public static async Task ThrowsAsync<T>(Func<Task> action) where T:Exception {Assertions++;try{await action();}catch(T){return;}throw new Exception("Expected "+typeof(T).Name);}
 private static readonly ServiceProvider Services=new ServiceCollection().AddLogging().AddOptions().BuildServiceProvider();
 public static DefaultHttpContext Context(string query=""){var c=new DefaultHttpContext();c.RequestServices=Services;c.Response.Body=new MemoryStream();c.Request.QueryString=new QueryString(query);return c;}
 public static DefaultHttpContext JsonRequest(string body){var c=Context();c.Request.ContentType="application/json";c.Request.Body=new MemoryStream(Encoding.UTF8.GetBytes(body));return c;}
 public static DefaultHttpContext FormRequest(string body){var c=Context();c.Request.ContentType="application/x-www-form-urlencoded";c.Request.Body=new MemoryStream(Encoding.UTF8.GetBytes(body));c.Request.ContentLength=c.Request.Body.Length;return c;}
 public static async Task<DefaultHttpContext> Execute(IResult result){var c=Context();await result.ExecuteAsync(c);return c;}
 public static string Body(HttpContext c)=>Encoding.UTF8.GetString(((MemoryStream)c.Response.Body).ToArray());
 public static void Json<T>(HttpContext c,string property,T expected){using var doc=JsonDocument.Parse(Body(c));Equal(JsonSerializer.Serialize(expected),doc.RootElement.GetProperty(property).GetRawText());}
 public static ClaimsPrincipal User(bool authenticated,string type,string value)=>new(new ClaimsIdentity(new[]{new Claim(type,value)},authenticated?"test":null));
 public static async IAsyncEnumerable<int> Sequence(params int[] values){foreach(var value in values){yield return value;await Task.Yield();}}
 public static DefaultHttpContext StartedContext(){var features=new FeatureCollection();features.Set<IHttpResponseFeature>(new StartedResponse());var c=new DefaultHttpContext(features);return c;}
 private sealed class StartedResponse:IHttpResponseFeature {
  public int StatusCode {get;set;}=200;public string? ReasonPhrase{get;set;}public IHeaderDictionary Headers{get;set;}=new HeaderDictionary();public Stream Body{get;set;}=new MemoryStream();public bool HasStarted=>true;
  public void OnStarting(Func<object,Task> callback,object state){}public void OnCompleted(Func<object,Task> callback,object state){}
 }
}
public sealed class ManualClock:TimeProvider {private DateTimeOffset now=new(2024,1,1,0,0,0,TimeSpan.Zero);public override DateTimeOffset GetUtcNow()=>now;public void Advance(TimeSpan delta)=>now+=delta;}
public static class JsonExtensions {public static bool TryGetInt32Safe(this JsonElement value,out int n){n=0;return value.ValueKind==JsonValueKind.Number&&value.TryGetInt32(out n);}}
`;
const project=`<Project Sdk="Microsoft.NET.Sdk">
 <PropertyGroup>
  <OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><Nullable>enable</Nullable><ImplicitUsings>enable</ImplicitUsings><LangVersion>14</LangVersion>
  <EnableDefaultCompileItems>false</EnableDefaultCompileItems><ExerciseSet Condition="'$(ExerciseSet)' == ''">solutions</ExerciseSet>
  <UseSharedCompilation>false</UseSharedCompilation><BuildInParallel>false</BuildInParallel><NuGetAudit>false</NuGetAudit>
 </PropertyGroup>
 <ItemGroup><FrameworkReference Include="Microsoft.AspNetCore.App"/><Compile Include="Program.cs;Support.cs;tests/*.cs"/><Compile Include="$(ExerciseSet)/*.cs"/></ItemGroup>
 <Target Name="ValidateExerciseSet" BeforeTargets="PrepareForBuild"><Error Condition="'$(ExerciseSet)' != 'solutions' and '$(ExerciseSet)' != 'starters'" Text="ExerciseSet must be starters or solutions"/></Target>
</Project>\n`;
const program=`using DotnetWeb;
CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;
CultureInfo.CurrentUICulture=CultureInfo.InvariantCulture;
var all=new (string Id,string Family,Func<Task> Run)[]{
${exercises.map(e=>` ("${e.id}",${q(e.family)},Tests${e.id}.Run),`).join('\n')}
};
string? id=null;string? output=null;
for(int i=0;i<args.Length;i++){if(args[i]=="--id"&&i+1<args.Length)id=args[++i];else if(args[i]=="--report"&&i+1<args.Length)output=args[++i];else{Console.Error.WriteLine("Invalid runner arguments");return 2;}}
var selected=id is null?all:all.Where(e=>e.Id==id).ToArray();
if(selected.Length==0||output is null){Console.Error.WriteLine("Unknown ID or missing report path");return 2;}
var results=new List<object>();int passed=0,failed=0;
foreach(var item in selected){var before=Check.Assertions;try{await item.Run();passed++;results.Add(new{id=item.Id,family=item.Family,passed=true,phase="tests",assertions=Check.Assertions-before});Console.WriteLine("PASS "+item.Id+" "+item.Family);}catch(Exception e){failed++;results.Add(new{id=item.Id,family=item.Family,passed=false,phase="tests",assertions=Check.Assertions-before,errorType=e.GetType().Name,error=e.Message});Console.WriteLine("FAIL "+item.Id+" "+e.GetType().Name+": "+e.Message);}}
File.WriteAllText(output,JsonSerializer.Serialize(new{phase="tests",groups=selected.Length,passed,failed,assertions=Check.Assertions,results},new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine($"Groups: {passed} passed, {failed} failed; assertions: {Check.Assertions}");
return failed==0?0:1;
`;
const verify=String.raw`'use strict';
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process'),assert=require('node:assert/strict');
let id,starters=false,inventory=false;
function main(){
 const args=process.argv.slice(2);
 for(let i=0;i<args.length;i++){const a=args[i];if(a==='--starters')starters=true;else if(a==='--inventory')inventory=true;else if(a==='--id'||a.startsWith('--id=')){if(id)throw Error('Duplicate id');const raw=a==='--id'?args[++i]:a.slice(5);if(!/^(?:W)?\d{1,3}$/i.test(raw||''))throw Error('ID must be 1..300 or W001..W300');const n=Number(raw.replace(/^W/i,''));if(n<1||n>300)throw Error('Unknown id '+raw);id='W'+String(n).padStart(3,'0');}else throw Error('Unknown option '+a);}
 const manifest=JSON.parse(fs.readFileSync(path.join(__dirname,'manifest.json'),'utf8'));
 assert.equal(manifest.length,300);assert.equal(new Set(manifest.map(x=>x.family)).size,30);
 manifest.forEach((row,i)=>{assert.equal(row.id,'W'+String(i+1).padStart(3,'0'));assert.equal(row.scenario,i%10+1);for(const k of ['prompt','starter','solution','test'])assert.ok(fs.statSync(path.join(__dirname,row[k])).isFile());});
 for(const folder of ['prompts','starters','solutions','tests'])assert.equal(fs.readdirSync(path.join(__dirname,folder)).length,300);
 const mode=starters?'starter':'solution',set=starters?'starters':'solutions',suffix=mode+(id?'-'+id:'');
 const reportFile=path.join(__dirname,'verification-'+suffix+'.json');
 const base={track:'dotnet-web-300',mode,scope:'in-process ASP.NET Core; no network',selected:id||'all',groups:id?1:300};
 if(inventory){const report={...base,phase:'inventory',inventory:{exercises:300,families:30,scenariosPerFamily:10},passed:300,failed:0};fs.writeFileSync(path.join(__dirname,'inventory.json'),JSON.stringify(report,null,2)+'\n');console.log('Inventory OK: 300 prompts/starters/solutions/shared tests; 30 families x10; W001..W300. No compile performed.');return 0;}
 const buildArgs=['build',path.join(__dirname,'WebExercises.csproj'),'--configuration','Debug','--nologo','--verbosity','minimal','--disable-build-servers','-m:1','-p:ExerciseSet='+set,'-p:RestoreConfigFile='+path.join(__dirname,'NuGet.Config')];
 console.log('Compile '+set+' only (300 independent classes; one sequential SDK project).');
 const built=cp.spawnSync('dotnet',buildArgs,{cwd:__dirname,encoding:'utf8',maxBuffer:32*1024*1024,timeout:600000,env:{...process.env,DOTNET_CLI_TELEMETRY_OPTOUT:'1',DOTNET_SKIP_FIRST_TIME_EXPERIENCE:'1'}});
 const buildLog=(built.stdout||'')+(built.stderr||'')+(built.error?String(built.error):'');fs.writeFileSync(path.join(__dirname,'build-'+suffix+'.log'),buildLog);process.stdout.write(buildLog);
 if(built.error||built.status!==0){fs.writeFileSync(reportFile,JSON.stringify({...base,phase:'build',passed:0,failed:0,notRun:base.groups,buildExitCode:built.status,error:built.error?String(built.error):'Build failed; see build log',results:[]},null,2)+'\n');return 2;}
 const raw=path.join(__dirname,'runtime-'+suffix+'.json');if(fs.existsSync(raw))fs.unlinkSync(raw);
 const runArgs=[path.join(__dirname,'bin','Debug','net10.0','WebExercises.dll'),'--report',raw];if(id)runArgs.push('--id',id);
 const ran=cp.spawnSync('dotnet',runArgs,{cwd:__dirname,encoding:'utf8',maxBuffer:32*1024*1024,timeout:600000,env:{...process.env,DOTNET_CLI_TELEMETRY_OPTOUT:'1'}});
 const testLog=(ran.stdout||'')+(ran.stderr||'')+(ran.error?String(ran.error):'');fs.writeFileSync(path.join(__dirname,'tests-'+suffix+'.log'),testLog);process.stdout.write(testLog);
 if(!fs.existsSync(raw)){fs.writeFileSync(reportFile,JSON.stringify({...base,phase:'tests',buildPassed:true,passed:0,failed:base.groups,error:'Runner failed to produce JSON',runnerExitCode:ran.status,results:[]},null,2)+'\n');return 1;}
 const report=JSON.parse(fs.readFileSync(raw,'utf8'));assert.equal(report.groups,base.groups);fs.writeFileSync(reportFile,JSON.stringify({...base,...report,buildPassed:true,buildExitCode:0,runnerExitCode:ran.status},null,2)+'\n');return ran.status===0&&report.failed===0?0:1;
}
try{process.exitCode=main();}catch(e){console.error(e.stack);process.exitCode=2;}
`;
// Fix JS regex escaping in raw template: the wrapper needs one backslash for digit classes.
const wrapper=verify.replaceAll('\\\\d','\\d');
const manifest=exercises.map(e=>({id:e.id,number:e.number,tech:'aspnetcore',family:e.family,scenario:e.scenario,variant:e.variant,title:e.family+' / scenario '+e.scenario+' — '+e.variant,scope:'in-process',prompt:'prompts/'+e.id+'.txt',starter:'starters/'+e.id+'.cs',solution:'solutions/'+e.id+'.cs',test:'tests/'+e.id+'.cs'}));
fs.mkdirSync(root);for(const folder of ['prompts','starters','solutions','tests'])fs.mkdirSync(path.join(root,folder));
const write=(name,body)=>fs.writeFileSync(path.join(root,name),body);
write('manifest.json',JSON.stringify(manifest,null,2)+'\n');write('WebExercises.csproj',project);write('NuGet.Config','<?xml version="1.0" encoding="utf-8"?><configuration><packageSources><clear /></packageSources></configuration>\n');write('Support.cs',helper);write('Program.cs',program);write('verify.cjs',wrapper);
for(const e of exercises){
 const header=`// ${e.id}: ${e.family} / scenario ${e.scenario}\n// ${e.variant}\n// Read prompts/${e.id}.txt. In-process ASP.NET Core contract, no network.\nnamespace DotnetWeb;\npublic static class ${e.id} {\n${e.extra}\n`;
 write('solutions/'+e.id+'.cs',header+` public static ${e.signature} {\n  ${e.body}\n }\n}\n`);
 write('starters/'+e.id+'.cs',header+` public static ${e.signature.replace(/^async /,'')} {\n  // TODO: implement independently. References are excluded from practice builds.\n  throw new NotImplementedException("${e.id}");\n }\n}\n`);
 write('tests/'+e.id+'.cs',`using static DotnetWeb.${e.id};\nnamespace DotnetWeb;\npublic static class Tests${e.id} { public static async Task Run() {\n await Task.CompletedTask;\n${e.tests.map((t,i)=>'{\n '+(i===0?' ':'')+t+'\n }').join('\n ')}\n} }\n`);
 write('prompts/'+e.id+'.txt',`${e.id} — ${e.family}\nScenario ${e.scenario}/10: ${e.variant}\n\n${e.prompt}\n\nSignature: public static ${e.signature}\n${e.extra?'Provided domain types: '+e.extra+'\n':''}\nEdit starters/${e.id}.cs. Run node dotnet-web-300/verify.cjs --starters --id=${e.id} from unionboot.\nReference: solutions/${e.id}.cs; shared checks: tests/${e.id}.cs.\nAll tests run in-process against actual ASP.NET Core types, not over a socket.\nThis is one of ten related family scenarios, not an unrelated concept.\nTests cover specified examples and edges, not a proof for every input.\n`);
}
write('GUIDE.txt',`DOTNET WEB 300 — ASP.NET CORE PRACTICE\n\n300 independent blank starters and reference solutions, W001..W300.\n30 meaningful web-development families x10 openly labelled scenario variants.\nSome lifetime/metadata families repeat the core implementation with different policies or labels: these are deliberate repetitions, not 300 distinct concepts.\nSeparate numbering from C#583 and JavaScript/React1718.\n\nREQUIREMENTS\nExisting .NET SDK10 and shared Microsoft.AspNetCore.App. No NuGet packages, installation or external access. NuGet.Config clears package sources.\n\nWORKFLOW (from unionboot)\nnode dotnet-web-300/verify.cjs --inventory\nnode dotnet-web-300/verify.cjs --id=W001\nnode dotnet-web-300/verify.cjs --starters --id=1\nnode dotnet-web-300/verify.cjs\nnode dotnet-web-300/verify.cjs --starters\n--id W001 also works. Choose one scenario from each family before doing policy variants.\nRead prompts/W001.txt, edit starters/W001.cs, use shared tests/W001.cs.\n\nBUILD ISOLATION\nOne SDK project compiles either solutions/*.cs OR starters/*.cs via ExerciseSet, never both. Even --id compiles the selected set of all300 before grading the requested group; an unrelated syntax error is therefore a build failure, not a failed exercise assertion.\nRun wrappers sequentially: both modes intentionally share one build output. Blank methods compile and throw NotImplementedException at runtime.\nWrapper: build failure exit2; grading failure exit1; all selected groups pass exit0; invalid flags/inventory exit2.\nReports verification-MODE[-WID].json contain groups, phase, per-group errors/assertions and buildPassed. Build and test logs remain alongside them. Inventory only validates files/IDs; it does NOT compile or claim reference correctness.\n\nSCOPE\nEvery group uses real ASP.NET Core HttpContext, IResult, DI, authorization, options or endpoint metadata. HTTP results are executed against DefaultHttpContext with MemoryStream where content matters. Metadata-only tests do not prove router or middleware integration. All tests are in-process; no server/socket/network integration is claimed. Auth exercises apply policies to synthetic principals, never parse credentials. Stores/clocks are deterministic and injected; cache/idempotency stores are explicitly sequential teaching stores, not production distributed implementations. No wall-clock sleeps or packages.\n\nGENERATOR\nnode build-dotnet-web-300.cjs refuses any existing dotnet-web-300 directory, with no overwrite escape hatch. Do not delete learner work to regenerate. Generator writes only this pack.\n\nFAMILIES\n${families.map((f,i)=>'W'+String(i*10+1).padStart(3,'0')+'..W'+String(i*10+10).padStart(3,'0')+' '+f.name).join('\n')}\n`);
console.log('Created '+root+': '+exercises.length+' exercises, '+families.length+' families. Run --inventory before compilation.');
